NEW_SERVICES = 'from services import (\n    check_inventory_lock as _check_inventory_lock,\n    acquire_inventory_location_guard,\n    apply_inventory_movement,\n    allocate_fefo_inventory,\n    InventoryMutationError,\n)'
START_MARKER = '# =================================================================================\n# [المرحلة الرابعة والخامسة] المحرك الموحد للحوالات ونظام الصلاحية (FEFO & IN_TRANSIT)\n# هذه الـ APIs لا تمس العمليات القديمة، بل تؤسس لهندسة الـ SaaS القادمة.\n# =================================================================================\n'
END_MARKER = '# =================================================================================\n# [المرحلة السادسة] محرك الجرد القانوني (Stocktake Engine)\n# =================================================================================\n'
TRANSFER_SECTION = '# =================================================================================\n# [المرحلة الرابعة والخامسة] المحرك الموحد للحوالات ونظام الصلاحية (FEFO & IN_TRANSIT)\n# =================================================================================\n\nasync def _check_fefo_override_permission(\n    db: AsyncSession,\n    admin: Driver,\n    company_id: int\n) -> bool:\n    """التحقق من صلاحية تجاوز FEFO داخل نفس الشركة."""\n    if admin.is_admin:\n        return True\n\n    stmt = select(Permission.id).select_from(UserRole).join(\n        Role,\n        and_(\n            UserRole.role_id == Role.id,\n            UserRole.company_id == company_id\n        )\n    ).join(\n        role_permissions,\n        Role.id == role_permissions.c.role_id\n    ).join(\n        Permission,\n        role_permissions.c.permission_id == Permission.id\n    ).filter(\n        UserRole.driver_id == admin.id,\n        UserRole.company_id == company_id,\n        Permission.code == \'inventory.fefo_override\'\n    )\n\n    if (await db.execute(stmt)).first() is None:\n        raise ValueError(\n            "مرفوض: تخطي نظام FEFO يتطلب صلاحية inventory.fefo_override."\n        )\n\n    return True\n\n\nasync def _reconcile_cycle_count_movements(\n    db: AsyncSession, company_id: int, location_id: int,\n    variant_id: int, batch_id: Optional[int],\n    cutoff_time: datetime\n) -> int:\n    """حساب صافي الحركات الواقعة على الصنف منذ نقطة الانطلاق لتسوية الجرد الدوري تلقائياً"""\n    stmt_in = select(func.coalesce(func.sum(InventoryMovement.quantity), 0)).filter(\n        InventoryMovement.company_id == company_id,\n        InventoryMovement.destination_location_id == location_id,\n        InventoryMovement.product_variant_id == variant_id,\n        InventoryMovement.created_at >= cutoff_time,\n        InventoryMovement.reference_type != \'AUDIT_ADJUSTMENT\'\n    )\n    if batch_id:\n        stmt_in = stmt_in.filter(InventoryMovement.batch_id == batch_id)\n    qty_in = (await db.execute(stmt_in)).scalar() or 0\n\n    stmt_out = select(func.coalesce(func.sum(InventoryMovement.quantity), 0)).filter(\n        InventoryMovement.company_id == company_id,\n        InventoryMovement.source_location_id == location_id,\n        InventoryMovement.product_variant_id == variant_id,\n        InventoryMovement.created_at >= cutoff_time,\n        InventoryMovement.reference_type != \'AUDIT_ADJUSTMENT\'\n    )\n    if batch_id:\n        stmt_out = stmt_out.filter(InventoryMovement.batch_id == batch_id)\n    qty_out = (await db.execute(stmt_out)).scalar() or 0\n\n    return int(qty_in - qty_out)\n\n\nasync def _upsert_inventory_balance(\n    db: AsyncSession,\n    company_id: int,\n    location_id: int,\n    variant_id: int,\n    batch_id: int,\n    qty_change: int\n):\n    """Legacy helper مؤقت للجرد فقط؛ سيُحذف في Phase 4."""\n    if qty_change < 0:\n        stmt_check = select(InventoryBalance.on_hand_quantity).filter_by(\n            company_id=company_id,\n            location_id=location_id,\n            product_variant_id=variant_id,\n            batch_id=batch_id,\n            stock_status=\'AVAILABLE\'\n        ).with_for_update()\n        current_qty = (await db.execute(stmt_check)).scalar() or 0\n        if current_qty + qty_change < 0:\n            raise ValueError(\n                f"لا يمكن سحب كمية ({abs(qty_change)}) تتجاوز الرصيد المتاح ({current_qty}) في الموقع."\n            )\n\n    stmt = pg_insert(InventoryBalance).values(\n        company_id=company_id,\n        location_id=location_id,\n        product_variant_id=variant_id,\n        batch_id=batch_id,\n        stock_status=\'AVAILABLE\',\n        on_hand_quantity=qty_change if qty_change > 0 else 0,\n        reserved_quantity=0\n    ).on_conflict_do_update(\n        index_elements=[\n            \'company_id\',\n            \'location_id\',\n            \'product_variant_id\',\n            \'batch_id\',\n            \'stock_status\'\n        ],\n        set_=dict(\n            on_hand_quantity=InventoryBalance.on_hand_quantity + qty_change\n        )\n    )\n    await db.execute(stmt)\n\n\nasync def _verify_location_ownership(\n    db: AsyncSession,\n    company_id: int,\n    *location_ids,\n    allowed_types: Optional[List[str]] = None\n):\n    """التحقق من الانتماء والحالة ونوع الموقع دون كشف بيانات Tenant آخر."""\n    unique_ids = sorted({int(loc_id) for loc_id in location_ids})\n\n    stmt = select(\n        InventoryLocation.id,\n        InventoryLocation.location_type,\n        InventoryLocation.is_active\n    ).filter(\n        InventoryLocation.company_id == company_id,\n        InventoryLocation.id.in_(unique_ids)\n    )\n    rows = (await db.execute(stmt)).all()\n    found = {\n        row.id: (row.location_type, bool(row.is_active))\n        for row in rows\n    }\n\n    if set(found) != set(unique_ids):\n        raise ValueError("مرفوض أمنياً: أحد المواقع غير موجود أو لا ينتمي للشركة.")\n\n    for loc_id in unique_ids:\n        location_type, is_active = found[loc_id]\n        if not is_active:\n            raise ValueError(f"مرفوض أمنياً: الموقع ({loc_id}) غير فعال.")\n        if allowed_types and location_type not in allowed_types:\n            raise ValueError(\n                f"مرفوض أمنياً: نوع الموقع ({location_type}) غير مسموح لهذه العملية."\n            )\n\n\nasync def _acquire_shared_inventory_guards(\n    db: AsyncSession,\n    company_id: int,\n    *location_ids: int\n) -> None:\n    """ترتيب حراس المواقع قبل أي Row Lock لمنع دورات Deadlock."""\n    for location_id in sorted({int(x) for x in location_ids}):\n        await acquire_inventory_location_guard(\n            db,\n            company_id,\n            location_id,\n            exclusive=False\n        )\n\n\n@router.post("/warehouse/unified/transfer/dispatch", status_code=200)\nasync def unified_transfer_dispatch(\n    payload: UnifiedDispatchRequest,\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    company_id = current_admin.company_id\n\n    try:\n        await _verify_location_ownership(\n            db,\n            company_id,\n            payload.source_location_id,\n            payload.destination_location_id,\n            allowed_types=[\'WAREHOUSE\', \'VEHICLE\']\n        )\n\n        requested_variant_ids = {\n            item.product_variant_id\n            for item in payload.items\n        }\n        valid_variant_ids = set(\n            (\n                await db.execute(\n                    select(ProductVariant.id).filter(\n                        ProductVariant.company_id == company_id,\n                        ProductVariant.id.in_(requested_variant_ids),\n                        ProductVariant.is_active.is_(True)\n                    )\n                )\n            ).scalars().all()\n        )\n        if valid_variant_ids != requested_variant_ids:\n            raise HTTPException(\n                status_code=400,\n                detail="يوجد صنف غير صالح أو غير فعال أو لا يتبع شركتك ضمن الحوالة."\n            )\n\n        stmt_transit_insert = pg_insert(InventoryLocation).values(\n            company_id=company_id,\n            name="بضاعة في الطريق",\n            code="TRANSIT-SYS",\n            location_type=\'IN_TRANSIT\',\n            is_active=True\n        ).on_conflict_do_nothing(\n            index_elements=[\'company_id\', \'code\']\n        )\n        await db.execute(stmt_transit_insert)\n\n        stmt_transit = select(InventoryLocation.id).filter_by(\n            company_id=company_id,\n            code=\'TRANSIT-SYS\',\n            location_type=\'IN_TRANSIT\',\n            is_active=True\n        )\n        transit_location_id = (\n            await db.execute(stmt_transit)\n        ).scalar_one_or_none()\n\n        if transit_location_id is None:\n            raise HTTPException(\n                status_code=409,\n                detail="تعذر تجهيز موقع IN_TRANSIT الخاص بالشركة."\n            )\n\n        await _acquire_shared_inventory_guards(\n            db,\n            company_id,\n            payload.source_location_id,\n            transit_location_id\n        )\n\n        transfer_ref = f"TRN-{uuid.uuid4().hex.upper()}"\n\n        header = InventoryTransferHeader(\n            company_id=company_id,\n            reference_number=transfer_ref,\n            source_location_id=payload.source_location_id,\n            destination_location_id=payload.destination_location_id,\n            transit_location_id=transit_location_id,\n            workflow_type=\'TRANSIT\',\n            status=\'IN_TRANSIT\',\n            dispatched_by=current_admin.id,\n            notes=payload.notes or None\n        )\n        db.add(header)\n        await db.flush()\n\n        ordered_items = sorted(\n            payload.items,\n            key=lambda item: (\n                int(item.product_variant_id),\n                int(item.override_batch_id or 0)\n            )\n        )\n\n        for item in ordered_items:\n            override_reason_id = None\n            override_actor_id = None\n            override_note = None\n\n            if item.is_fefo_override:\n                await _check_fefo_override_permission(\n                    db,\n                    current_admin,\n                    company_id\n                )\n\n                reason_row = (\n                    await db.execute(\n                        select(\n                            OverrideReason.id,\n                            OverrideReason.description\n                        ).filter_by(\n                            id=item.override_reason_id,\n                            company_id=company_id,\n                            is_active=True\n                        )\n                    )\n                ).one_or_none()\n\n                if reason_row is None:\n                    raise HTTPException(\n                        status_code=400,\n                        detail="سبب تجاوز FEFO غير موجود أو غير فعال في شركتك."\n                    )\n\n                batch_exists = (\n                    await db.execute(\n                        select(ProductBatch.id).filter(\n                            ProductBatch.id == item.override_batch_id,\n                            ProductBatch.company_id == company_id,\n                            ProductBatch.product_variant_id == item.product_variant_id,\n                            ProductBatch.is_active.is_(True),\n                            ProductBatch.expiry_date >= date.today()\n                        )\n                    )\n                ).scalar_one_or_none()\n\n                if batch_exists is None:\n                    raise HTTPException(\n                        status_code=400,\n                        detail=(\n                            "الدفعة المحددة لتجاوز FEFO غير صالحة أو منتهية "\n                            "أو لا تتبع الصنف/الشركة."\n                        )\n                    )\n\n                try:\n                    expected_fefo = await allocate_fefo_inventory(\n                        db,\n                        company_id=company_id,\n                        location_id=payload.source_location_id,\n                        product_variant_id=item.product_variant_id,\n                        quantity=1\n                    )\n                    expected_batch_id = (\n                        expected_fefo[0][0]\n                        if expected_fefo\n                        else None\n                    )\n                except InventoryMutationError:\n                    expected_batch_id = None\n\n                allocations = [\n                    (int(item.override_batch_id), int(item.quantity))\n                ]\n                override_reason_id = int(item.override_reason_id)\n                override_actor_id = current_admin.id\n                override_note = str(reason_row.description or "")[:255]\n\n                db.add(SystemAuditLog(\n                    company_id=company_id,\n                    admin_id=current_admin.id,\n                    target_id=f"Transfer_{header.id}",\n                    action_type="FEFO_OVERRIDE",\n                    old_value=(\n                        f"Expected FEFO Batch: {expected_batch_id}"\n                        if expected_batch_id is not None\n                        else "Expected FEFO Batch: unavailable"\n                    ),\n                    new_value=(\n                        f"Chosen Batch: {item.override_batch_id}, "\n                        f"Reason ID: {item.override_reason_id}"\n                    )\n                ))\n            else:\n                allocations = await allocate_fefo_inventory(\n                    db,\n                    company_id=company_id,\n                    location_id=payload.source_location_id,\n                    product_variant_id=item.product_variant_id,\n                    quantity=item.quantity\n                )\n\n            for batch_id, take_qty in allocations:\n                line = InventoryTransferLine(\n                    company_id=company_id,\n                    transfer_header_id=header.id,\n                    product_variant_id=item.product_variant_id,\n                    batch_id=batch_id,\n                    quantity=take_qty,\n                    fefo_override_reason_id=override_reason_id,\n                    fefo_overridden_by=override_actor_id,\n                    fefo_override_note=override_note\n                )\n                db.add(line)\n\n                await apply_inventory_movement(\n                    db,\n                    company_id=company_id,\n                    performed_by=current_admin.id,\n                    product_variant_id=item.product_variant_id,\n                    batch_id=batch_id,\n                    quantity=take_qty,\n                    movement_kind=\'PHYSICAL\',\n                    reference_type=\'TRANSFER_DISPATCH\',\n                    reference_id=transfer_ref,\n                    idempotency_key=(\n                        f"TRN-DISP-{header.id}-"\n                        f"{item.product_variant_id}-{batch_id}"\n                    ),\n                    source_location_id=payload.source_location_id,\n                    destination_location_id=transit_location_id,\n                    source_stock_status=\'AVAILABLE\',\n                    destination_stock_status=\'AVAILABLE\',\n                    transfer_header_id=header.id,\n                    notes=payload.notes or None\n                )\n\n        await db.commit()\n\n        return {\n            "message": "تم تحميل البضاعة بنجاح وهي الآن في الطريق.",\n            "transfer_reference": transfer_ref,\n            "header_id": header.id\n        }\n\n    except HTTPException:\n        await db.rollback()\n        raise\n    except InventoryMutationError as e:\n        await db.rollback()\n        raise HTTPException(status_code=409, detail=str(e))\n    except ValueError as e:\n        await db.rollback()\n        raise HTTPException(status_code=403, detail=str(e))\n    except IntegrityError as e:\n        await db.rollback()\n        logger.warning(\n            f"تعارض متزامن أثناء إنشاء الحوالة: {str(e)}",\n            exc_info=True\n        )\n        raise HTTPException(\n            status_code=409,\n            detail="حدث تعارض متزامن أثناء إنشاء الحوالة. لم يتم حفظ أي جزء منها."\n        )\n    except Exception as e:\n        await db.rollback()\n        logger.error(\n            f"خطأ في إنشاء الحوالة: {str(e)}",\n            exc_info=True\n        )\n        raise HTTPException(\n            status_code=500,\n            detail="خطأ داخلي أثناء معالجة الحوالة."\n        )\n\n\n@router.post("/warehouse/unified/transfer/receive", status_code=200)\nasync def unified_transfer_receive(\n    payload: UnifiedReceiveRequest,\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    company_id = current_admin.company_id\n\n    try:\n        stmt_header = select(\n            InventoryTransferHeader\n        ).filter_by(\n            id=payload.transfer_header_id,\n            company_id=company_id\n        ).with_for_update()\n\n        header = (\n            await db.execute(stmt_header)\n        ).scalar_one_or_none()\n\n        if header is None:\n            raise HTTPException(\n                status_code=404,\n                detail="الحوالة غير موجودة أو لا تتبع شركتك."\n            )\n\n        if header.workflow_type != \'TRANSIT\' or header.status != \'IN_TRANSIT\':\n            raise HTTPException(\n                status_code=409,\n                detail=f"لا يمكن استلام الحوالة بحالتها الحالية ({header.status})."\n            )\n\n        if header.destination_location_id != payload.destination_location_id:\n            raise HTTPException(\n                status_code=409,\n                detail="الوجهة المرسلة لا تطابق الوجهة الأصلية للحوالة."\n            )\n\n        if header.dispatched_by == current_admin.id:\n            raise HTTPException(\n                status_code=403,\n                detail="مرفوض رقابياً: لا يمكن للمُرسل تأكيد استلام نفس الحوالة."\n            )\n\n        await _verify_location_ownership(\n            db,\n            company_id,\n            payload.destination_location_id,\n            allowed_types=[\'WAREHOUSE\', \'VEHICLE\']\n        )\n\n        transit_location_id = header.transit_location_id\n        if transit_location_id is None:\n            raise HTTPException(\n                status_code=409,\n                detail="الحوالة لا تحمل موقع IN_TRANSIT صالحاً."\n            )\n\n        await _verify_location_ownership(\n            db,\n            company_id,\n            transit_location_id,\n            allowed_types=[\'IN_TRANSIT\']\n        )\n\n        await _acquire_shared_inventory_guards(\n            db,\n            company_id,\n            transit_location_id,\n            payload.destination_location_id\n        )\n\n        lines = (\n            await db.execute(\n                select(InventoryTransferLine).filter_by(\n                    company_id=company_id,\n                    transfer_header_id=header.id\n                ).order_by(\n                    InventoryTransferLine.product_variant_id.asc(),\n                    InventoryTransferLine.batch_id.asc(),\n                    InventoryTransferLine.id.asc()\n                )\n            )\n        ).scalars().all()\n\n        if not lines:\n            raise HTTPException(\n                status_code=409,\n                detail="الحوالة لا تحتوي على أسطر مخزون صالحة."\n            )\n\n        for line in lines:\n            await apply_inventory_movement(\n                db,\n                company_id=company_id,\n                performed_by=current_admin.id,\n                product_variant_id=line.product_variant_id,\n                batch_id=line.batch_id,\n                quantity=line.quantity,\n                movement_kind=\'PHYSICAL\',\n                reference_type=\'TRANSFER_RECEIPT\',\n                reference_id=header.reference_number,\n                idempotency_key=f"TRN-REC-{header.id}-{line.id}",\n                source_location_id=transit_location_id,\n                destination_location_id=payload.destination_location_id,\n                source_stock_status=\'AVAILABLE\',\n                destination_stock_status=\'AVAILABLE\',\n                transfer_header_id=header.id,\n                notes=header.notes\n            )\n\n        now_utc = datetime.now(timezone.utc).replace(tzinfo=None)\n\n        header.received_by = current_admin.id\n        header.accepted_at = now_utc\n        header.posted_at = now_utc\n        header.updated_at = now_utc\n        header.status = \'POSTED\'\n\n        db.add(SystemAuditLog(\n            company_id=company_id,\n            admin_id=current_admin.id,\n            target_id=f"Transfer_{header.id}",\n            action_type="TRANSFER_RECEIVED",\n            old_value="IN_TRANSIT",\n            new_value=f"POSTED by Admin {current_admin.id}"\n        ))\n\n        await db.commit()\n\n        return {\n            "message": "تم تأكيد الاستلام وترحيل الحوالة بنجاح."\n        }\n\n    except HTTPException:\n        await db.rollback()\n        raise\n    except InventoryMutationError as e:\n        await db.rollback()\n        raise HTTPException(status_code=409, detail=str(e))\n    except ValueError as e:\n        await db.rollback()\n        raise HTTPException(status_code=403, detail=str(e))\n    except IntegrityError as e:\n        await db.rollback()\n        logger.warning(\n            f"تعارض متزامن أثناء استلام الحوالة: {str(e)}",\n            exc_info=True\n        )\n        raise HTTPException(\n            status_code=409,\n            detail="حدث تعارض متزامن أثناء الاستلام. لم يتم حفظ عملية جزئية."\n        )\n    except Exception as e:\n        await db.rollback()\n        logger.error(\n            f"خطأ في استلام الحوالة: {str(e)}",\n            exc_info=True\n        )\n        raise HTTPException(\n            status_code=500,\n            detail="خطأ داخلي أثناء استلام الحوالة."\n        )\n\n\n@router.post("/warehouse/unified/transfer/{header_id}/cancel", status_code=200)\nasync def unified_transfer_cancel(\n    header_id: int,\n    decision_reason: str = Body(..., embed=True),\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    company_id = current_admin.company_id\n    reason = decision_reason.strip()\n\n    if not reason or len(reason) > 2000:\n        raise HTTPException(\n            status_code=422,\n            detail="سبب الإلغاء مطلوب ويجب ألا يتجاوز 2000 حرف."\n        )\n\n    try:\n        header = (\n            await db.execute(\n                select(InventoryTransferHeader).filter_by(\n                    id=header_id,\n                    company_id=company_id\n                ).with_for_update()\n            )\n        ).scalar_one_or_none()\n\n        if header is None:\n            raise HTTPException(\n                status_code=404,\n                detail="الحوالة غير موجودة أو لا تتبع شركتك."\n            )\n\n        if header.workflow_type != \'TRANSIT\' or header.status != \'IN_TRANSIT\':\n            raise HTTPException(\n                status_code=409,\n                detail=f"لا يمكن إلغاء الحوالة بحالتها الحالية ({header.status})."\n            )\n\n        transit_location_id = header.transit_location_id\n        if transit_location_id is None:\n            raise HTTPException(\n                status_code=409,\n                detail="الحوالة لا تحمل موقع IN_TRANSIT صالحاً."\n            )\n\n        await _verify_location_ownership(\n            db,\n            company_id,\n            header.source_location_id,\n            allowed_types=[\'WAREHOUSE\', \'VEHICLE\']\n        )\n        await _verify_location_ownership(\n            db,\n            company_id,\n            transit_location_id,\n            allowed_types=[\'IN_TRANSIT\']\n        )\n\n        await _acquire_shared_inventory_guards(\n            db,\n            company_id,\n            transit_location_id,\n            header.source_location_id\n        )\n\n        lines = (\n            await db.execute(\n                select(InventoryTransferLine).filter_by(\n                    company_id=company_id,\n                    transfer_header_id=header.id\n                ).order_by(\n                    InventoryTransferLine.product_variant_id.asc(),\n                    InventoryTransferLine.batch_id.asc(),\n                    InventoryTransferLine.id.asc()\n                )\n            )\n        ).scalars().all()\n\n        if not lines:\n            raise HTTPException(\n                status_code=409,\n                detail="الحوالة لا تحتوي على أسطر مخزون صالحة."\n            )\n\n        for line in lines:\n            await apply_inventory_movement(\n                db,\n                company_id=company_id,\n                performed_by=current_admin.id,\n                product_variant_id=line.product_variant_id,\n                batch_id=line.batch_id,\n                quantity=line.quantity,\n                movement_kind=\'PHYSICAL\',\n                reference_type=\'TRANSFER_CANCELLED\',\n                reference_id=header.reference_number,\n                idempotency_key=f"TRN-CANC-{header.id}-{line.id}",\n                source_location_id=transit_location_id,\n                destination_location_id=header.source_location_id,\n                source_stock_status=\'AVAILABLE\',\n                destination_stock_status=\'AVAILABLE\',\n                transfer_header_id=header.id,\n                notes=reason\n            )\n\n        now_utc = datetime.now(timezone.utc).replace(tzinfo=None)\n\n        header.status = \'CANCELLED\'\n        header.cancelled_by = current_admin.id\n        header.cancelled_at = now_utc\n        header.decision_reason = reason\n        header.updated_at = now_utc\n\n        db.add(SystemAuditLog(\n            company_id=company_id,\n            admin_id=current_admin.id,\n            target_id=f"Transfer_{header.id}",\n            action_type="TRANSFER_CANCELLED",\n            old_value="IN_TRANSIT",\n            new_value=reason\n        ))\n\n        await db.commit()\n\n        return {\n            "message": "تم إلغاء الحوالة وإرجاع البضاعة للمصدر بنجاح."\n        }\n\n    except HTTPException:\n        await db.rollback()\n        raise\n    except InventoryMutationError as e:\n        await db.rollback()\n        raise HTTPException(status_code=409, detail=str(e))\n    except ValueError as e:\n        await db.rollback()\n        raise HTTPException(status_code=403, detail=str(e))\n    except IntegrityError as e:\n        await db.rollback()\n        raise HTTPException(\n            status_code=409,\n            detail="حدث تعارض متزامن أثناء إلغاء الحوالة. لم يتم حفظ عملية جزئية."\n        )\n    except Exception as e:\n        await db.rollback()\n        logger.error(\n            f"خطأ في إلغاء الحوالة: {str(e)}",\n            exc_info=True\n        )\n        raise HTTPException(\n            status_code=500,\n            detail="خطأ داخلي أثناء إلغاء الحوالة."\n        )\n\n\n@router.post("/warehouse/unified/transfer/{header_id}/reject", status_code=200)\nasync def unified_transfer_reject(\n    header_id: int,\n    decision_reason: str = Body(..., embed=True),\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    company_id = current_admin.company_id\n    reason = decision_reason.strip()\n\n    if not reason or len(reason) > 2000:\n        raise HTTPException(\n            status_code=422,\n            detail="سبب الرفض مطلوب ويجب ألا يتجاوز 2000 حرف."\n        )\n\n    try:\n        header = (\n            await db.execute(\n                select(InventoryTransferHeader).filter_by(\n                    id=header_id,\n                    company_id=company_id\n                ).with_for_update()\n            )\n        ).scalar_one_or_none()\n\n        if header is None:\n            raise HTTPException(\n                status_code=404,\n                detail="الحوالة غير موجودة أو لا تتبع شركتك."\n            )\n\n        if header.workflow_type != \'TRANSIT\' or header.status != \'IN_TRANSIT\':\n            raise HTTPException(\n                status_code=409,\n                detail=f"لا يمكن رفض الحوالة بحالتها الحالية ({header.status})."\n            )\n\n        if header.dispatched_by == current_admin.id:\n            raise HTTPException(\n                status_code=403,\n                detail="مرفوض رقابياً: لا يمكن للمُرسل رفض نفس الحوالة بصفته مستلماً."\n            )\n\n        await _verify_location_ownership(\n            db,\n            company_id,\n            header.destination_location_id,\n            allowed_types=[\'WAREHOUSE\', \'VEHICLE\']\n        )\n\n        transit_location_id = header.transit_location_id\n        if transit_location_id is None:\n            raise HTTPException(\n                status_code=409,\n                detail="الحوالة لا تحمل موقع IN_TRANSIT صالحاً."\n            )\n\n        await _verify_location_ownership(\n            db,\n            company_id,\n            header.source_location_id,\n            allowed_types=[\'WAREHOUSE\', \'VEHICLE\']\n        )\n        await _verify_location_ownership(\n            db,\n            company_id,\n            transit_location_id,\n            allowed_types=[\'IN_TRANSIT\']\n        )\n\n        await _acquire_shared_inventory_guards(\n            db,\n            company_id,\n            transit_location_id,\n            header.source_location_id\n        )\n\n        lines = (\n            await db.execute(\n                select(InventoryTransferLine).filter_by(\n                    company_id=company_id,\n                    transfer_header_id=header.id\n                ).order_by(\n                    InventoryTransferLine.product_variant_id.asc(),\n                    InventoryTransferLine.batch_id.asc(),\n                    InventoryTransferLine.id.asc()\n                )\n            )\n        ).scalars().all()\n\n        if not lines:\n            raise HTTPException(\n                status_code=409,\n                detail="الحوالة لا تحتوي على أسطر مخزون صالحة."\n            )\n\n        for line in lines:\n            await apply_inventory_movement(\n                db,\n                company_id=company_id,\n                performed_by=current_admin.id,\n                product_variant_id=line.product_variant_id,\n                batch_id=line.batch_id,\n                quantity=line.quantity,\n                movement_kind=\'PHYSICAL\',\n                reference_type=\'TRANSFER_REJECTED\',\n                reference_id=header.reference_number,\n                idempotency_key=f"TRN-REJ-{header.id}-{line.id}",\n                source_location_id=transit_location_id,\n                destination_location_id=header.source_location_id,\n                source_stock_status=\'AVAILABLE\',\n                destination_stock_status=\'AVAILABLE\',\n                transfer_header_id=header.id,\n                notes=reason\n            )\n\n        now_utc = datetime.now(timezone.utc).replace(tzinfo=None)\n\n        header.status = \'REJECTED\'\n        header.received_by = current_admin.id\n        header.rejected_at = now_utc\n        header.decision_reason = reason\n        header.updated_at = now_utc\n\n        db.add(SystemAuditLog(\n            company_id=company_id,\n            admin_id=current_admin.id,\n            target_id=f"Transfer_{header.id}",\n            action_type="TRANSFER_REJECTED",\n            old_value="IN_TRANSIT",\n            new_value=reason\n        ))\n\n        await db.commit()\n\n        return {\n            "message": "تم رفض الحوالة وإرجاع البضاعة لعهدة المصدر."\n        }\n\n    except HTTPException:\n        await db.rollback()\n        raise\n    except InventoryMutationError as e:\n        await db.rollback()\n        raise HTTPException(status_code=409, detail=str(e))\n    except ValueError as e:\n        await db.rollback()\n        raise HTTPException(status_code=403, detail=str(e))\n    except IntegrityError as e:\n        await db.rollback()\n        raise HTTPException(\n            status_code=409,\n            detail="حدث تعارض متزامن أثناء رفض الحوالة. لم يتم حفظ عملية جزئية."\n        )\n    except Exception as e:\n        await db.rollback()\n        logger.error(\n            f"خطأ في رفض الحوالة: {str(e)}",\n            exc_info=True\n        )\n        raise HTTPException(\n            status_code=500,\n            detail="خطأ داخلي أثناء رفض الحوالة."\n        )\n\n\n'

def normalize_newlines(data: bytes) -> bytes:
    return data.replace(b"\r\n", b"\n").replace(b"\r", b"\n")

def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(f"blob {len(data)}\0".encode("ascii") + data).hexdigest()

def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"Expected one {label}, found {count}.")
    return text.replace(old, new, 1)

def replace_section(text: str) -> str:
    start = text.find(START_MARKER)
    if start < 0:
        raise RuntimeError("Transfer section start marker not found.")
    end = text.find(END_MARKER, start + len(START_MARKER))
    if end < 0:
        raise RuntimeError("Stocktake section marker not found.")
    return text[:start] + TRANSFER_SECTION + text[end:]

def main() -> None:
    if not TARGET.exists():
        raise SystemExit(f"ERROR: الملف غير موجود: {TARGET}")

    raw = TARGET.read_bytes()
    uses_crlf = b"\r\n" in raw
    normalized = normalize_newlines(raw)
    current_sha = git_blob_sha(normalized)

    if current_sha != EXPECTED_NORMALIZED_GIT_BLOB_SHA:
        raise SystemExit(
            "ERROR: محتوى warehouse.py مختلف عن النسخة التي بُني عليها Phase 3.\n"
            f"Expected normalized SHA: {EXPECTED_NORMALIZED_GIT_BLOB_SHA}\n"
            f"Current  normalized SHA: {current_sha}\n"
            "لم يتم تعديل أي شيء."
        )

    text = normalized.decode("utf-8")
    text = replace_once(text, OLD_FASTAPI, NEW_FASTAPI, "FastAPI import")
    text = replace_once(text, OLD_SERVICES, NEW_SERVICES, "services import")
    text = replace_section(text)

    compile(text, str(TARGET), "exec")

    transfer_start = text.find("# [المرحلة الرابعة والخامسة]")
    stocktake_start = text.find("# [المرحلة السادسة]", transfer_start)
    transfer_slice = text[transfer_start:stocktake_start]

    forbidden = (
        "_allocate_fefo_batches",
        "status='PENDING'",
        "status != 'PENDING'",
        "db.add(InventoryMovement(",
        "_upsert_inventory_balance(db, company_id, transit",
        "role_permissions.c.permission_id\n    ).join(",
    )
    leftovers = [x for x in forbidden if x in transfer_slice]
    if leftovers:
        raise RuntimeError("Phase 3 validation failed: " + ", ".join(leftovers))

    required = (
        "workflow_type='TRANSIT'",
        "status='IN_TRANSIT'",
        "transit_location_id=transit_location_id",
        "transfer_header_id=header.id",
        "allocate_fefo_inventory(",
        "apply_inventory_movement(",
        "fefo_override_reason_id=override_reason_id",
        "header.cancelled_by = current_admin.id",
        "header.rejected_at = now_utc",
        "decision_reason: str = Body(..., embed=True)",
        "role_permissions.c.role_id",
    )
    missing = [x for x in required if x not in transfer_slice]
    if missing:
        raise RuntimeError("Phase 3 required contract missing: " + ", ".join(missing))

    output = text.encode("utf-8")
    if uses_crlf:
        output = output.replace(b"\n", b"\r\n")

    temp = TARGET.with_suffix(".py.phase3.tmp")
    temp.write_bytes(output)
    temp.replace(TARGET)

    final_raw = TARGET.read_bytes()
    final_norm = normalize_newlines(final_raw)

    print("WAREHOUSE_PHASE3_APPLIED_OK")
    print(f"Raw Git blob SHA: {git_blob_sha(final_raw)}")
    print(f"Normalized Git blob SHA: {git_blob_sha(final_norm)}")
    print("Changed: unified TRANSIT lifecycle + FEFO service + override audit + transfer isolation/concurrency")
    print("Next: python -m py_compile wa_backend/api/warehouse.py")

if __name__ == "__main__":
    main()
